func TestEveryModelCallResolvesItsBudgetFromConfig(t *testing.T) {
	fset, files := parsePackage(t) // parser.ParseDir(".", non-test files, 0 = no comments
	checked := 0
	for name, file := range files {
		short := shortName(name)
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Body == nil {
				continue
			}
			resolverInScope := callsTheResolver(fn.Body)
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				method, optsArg, ok := isModelCall(node) // GenerateText | GenerateWithImages
				if !ok {
					return true
				}
				checked++
				if why, unbuilt := describeUnbuiltOptions(optsArg); unbuilt {
					t.Errorf("%s:%d %s() is handed %s.", short, fset.Position(node.Pos()).Line, method, why)
					return true
				}
				if short == canonicalBudgetBuilder || resolverInScope {
					return true
				}
				t.Errorf("%s:%d %s() is called from %s, which never calls llmOptionsFromConfig.",
					short, fset.Position(node.Pos()).Line, method, fn.Name.Name)
				return true
			})
		}
	}
	if checked == 0 {
		t.Fatal("no GenerateText/GenerateWithImages call found in this package — this audit is no longer watching anything and must be repointed, not deleted")
	}
}

func TestNoHardcodedTokenBudget(t *testing.T) {
	fset, files := parsePackage(t)
	writes := 0
	for name, file := range files {
		ast.Inspect(file, func(node ast.Node) bool {
			switch n := node.(type) {
			case *ast.AssignStmt: // options["max_tokens"] = 2000
				for i, lhs := range n.Lhs {
					idx, ok := lhs.(*ast.IndexExpr)
					if !ok || !isBudgetKey(idx.Index) {
						continue
					}
					writes++
					if i < len(n.Rhs) && isNumericLiteral(n.Rhs[i]) {
						t.Errorf("%s:%d assigns a hardcoded number to a token budget.", shortName(name), fset.Position(n.Pos()).Line)
					}
				}
			case *ast.KeyValueExpr: // map[string]interface{}{"max_tokens": 4096}
				if !isBudgetKey(n.Key) {
					return true
				}
				writes++
				if isNumericLiteral(n.Value) {
					t.Errorf("%s:%d puts a hardcoded number in a map literal for a token budget.", shortName(name), fset.Position(n.Pos()).Line)
				}
			}
			return true
		})
	}
	if writes == 0 {
		t.Fatal("no max_tokens/budget_tokens write found anywhere in this package — the key has been renamed and this audit is now vacuous")
	}
}

func TestTheCanonicalBuilderStillResolvesFromConfig(t *testing.T) {
	_, files := parsePackage(t)
	var canonical *ast.File
	for name, file := range files {
		if shortName(name) == canonicalBudgetBuilder {
			canonical = file
		}
	}
	if canonical == nil {
		t.Fatalf("%s is not in this package any more — the exemption now excuses a file that does not exist", canonicalBudgetBuilder)
	}
	resolvesFromConfig := false
	ast.Inspect(canonical, func(node ast.Node) bool {
		assign, ok := node.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for i, lhs := range assign.Lhs {
			idx, ok := lhs.(*ast.IndexExpr)
			if !ok || !isBudgetKey(idx.Index) {
				continue
			}
			if i < len(assign.Rhs) && !isNumericLiteral(assign.Rhs[i]) {
				resolvesFromConfig = true
			}
		}
		return true
	})
	if !resolvesFromConfig {
		t.Fatalf("%s no longer computes a token budget from anything — it is exempted ONLY because it is the canonical resolver", canonicalBudgetBuilder)
	}
}
